//! Exact metadata shapes transcribed from qualified helper21/node2/guard2.
//! Opaque Request/accounting remain Value here; production constructors still
//! own their full typed semantics. This boundary only rejects structural drift.
use crate::io::Bound;use anyhow::Result;use serde::Deserialize;use serde_json::Value;use std::path::PathBuf;
#[derive(Deserialize)]#[serde(deny_unknown_fields)]#[allow(dead_code)]struct Runtime{schema:String,node:Bound,guard:Bound,admission_program:Bound,input_policy:Bound,admission:Bound,admission_capsule:Bound,input_acceptance:Bound,first_slot_source:Bound,memory:Bound,memory_completion:Bound,data:Bound,data_completion:Bound,maximum_runtime_seconds:u64,maximum_replayed_slots:u64,maximum_output_bytes:u64,exporter_floor_bytes:u64}
#[derive(Deserialize)]#[serde(deny_unknown_fields)]#[allow(dead_code)]struct GuardPlan{schema:String,parent_unit:String,parent_invocation_id:String,parent_program:Bound,parent_argv:Vec<String>,parent_start_ticks:u64,input_policy:Bound,admission:Bound,selected_memory_receipt:Bound,selected_memory_original_completion:Bound,selected_data_receipt:Bound,selected_data_original_completion:Bound,filesystem:PathBuf,minimum_free_bytes:u64,maximum_worker_vmas:u64,guard_timer:String,output_directory:PathBuf}
#[derive(Deserialize)]#[serde(deny_unknown_fields)]#[allow(dead_code)]struct Enrollment{schema:String,input_policy:Bound,admission:Bound,guard_plan:Bound,parent_service:Bound,guard_service:Bound,fallback_service:Bound,timer_source:Bound,first_guard:Bound,fleet_handoff:Bound,output:PathBuf}
#[derive(Deserialize)]#[serde(deny_unknown_fields)]#[allow(dead_code)]struct HeldTransition{schema:String,admission:Bound,enrollment:Bound,predecessor_fleet:Bound,predecessor_plan:Bound,successor_fleet:Bound,successor_plan:Bound,fleet_original_completion:Bound}
#[derive(Deserialize)]#[serde(deny_unknown_fields)]#[allow(dead_code)]struct Release{schema:String,enrollment:Bound,runtime_plan:Bound,current_phase_ledger:Bound,memory_request:Value,data_policy:Bound,data_policy_seal:Bound,resource_accounting:Value,#[serde(default)]held_transition:Option<Bound>}
pub fn validate(value:&Value)->Result<()>{match value["schema"].as_str(){Some("epoch163-first-output128-private-plan-v1")=>{let _:Runtime=serde_json::from_value(value.clone())?;},Some("epoch163-first-output128-memory-DATA-reserve-vma-guard-plan-v1")=>{let _:GuardPlan=serde_json::from_value(value.clone())?;},Some("epoch163-first-output128-enrollment-spec-v1")=>{let _:Enrollment=serde_json::from_value(value.clone())?;},Some("epoch163-first128-held-enrollment-release-transition-v1")=>{let _:HeldTransition=serde_json::from_value(value.clone())?;},Some("epoch163-first-output128-held-release-spec-v1")=>{let _:Release=serde_json::from_value(value.clone())?;},_=>()}Ok(())}
#[cfg(test)]mod tests{use super::*;use serde_json::json;#[test]fn held_transition_rejects_cross_schema_extra_or_missing_field(){let b=json!({"path":"/normal/x.json","sha256":"a".repeat(64)});let value=json!({"schema":"epoch163-first128-held-enrollment-release-transition-v1","admission":b,"enrollment":b,"predecessor_fleet":b,"predecessor_plan":b,"successor_fleet":b,"successor_plan":b,"fleet_original_completion":b});validate(&value).unwrap();let mut extra=value.clone();extra["new_resource_sample"]=json!(true);assert!(validate(&extra).is_err());let mut missing=value;missing.as_object_mut().unwrap().remove("fleet_original_completion");assert!(validate(&missing).is_err());}}
